const fs = require('fs');
const data = fs.readFileSync('/workspace/world.db');
// Check if it's actually SQLite
console.log(data.slice(0, 20).toString());
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
tables.forEach(t => {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ' columns:', cols.map(c => c.name));
});
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Search for the product by name or id
let rows = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-FA0948' OR name LIKE '%M310%' OR name LIKE '%LogiTech Wireless Mouse%'\").all();
console.log('Products found:', rows.length);
rows.forEach(r => {
  console.log(JSON.stringify(r, null, 2));
});
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check rt_variants for this product
let variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log('rt_variants:', JSON.stringify(variants, null, 2));

// Also check compatible products
const compatIds = ['PROD-B98D14','PROD-2DBA15','PROD-7C0240','PROD-73FAB4'];
compatIds.forEach(id => {
  const p = db.prepare('SELECT product_id, name, category FROM products WHERE product_id = ?').get(id);
  console.log('Compatible product:', JSON.stringify(p));
});
"

